const sale = $json.body;
if (!sale || typeof sale !== 'object' || Array.isArray(sale)) {
  throw new Error('Expected a form-urlencoded Gumroad Ping body');
}

const text = (value) => typeof value === 'string' ? value.trim() : '';
const flag = (value) => value === true || value === 1 || ['true', '1'].includes(text(value).toLowerCase());
const saleId = text(sale.sale_id) || text(sale.id);
if (!saleId) {
  throw new Error('sale_id is required');
}

const price = typeof sale.price === 'number' ? sale.price : text(sale.price);
if (typeof price === 'string' && !/^-?[0-9]+$/.test(price)) {
  throw new Error('price must be an integer in cents');
}
const cents = Number(price);
if (!Number.isSafeInteger(cents)) {
  throw new Error('price must be a safe integer in cents');
}

const timestamp = text(sale.sale_timestamp) || text(sale.created_at);
const iso = /^([0-9]{4}-[0-9]{2}-[0-9]{2})T(?:[01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](?:\.[0-9]+)?(?:Z|[+-](?:[01][0-9]|2[0-3]):[0-5][0-9])$/;
const parts = iso.exec(timestamp);
if (!parts || parts[1].startsWith('0000-')) {
  throw new Error('sale_timestamp must be an ISO 8601 timestamp with a timezone');
}
const date = new Date(timestamp);
const calendarDay = new Date(parts[1] + 'T00:00:00Z');
if (!Number.isFinite(date.valueOf()) || !Number.isFinite(calendarDay.valueOf())
    || calendarDay.toISOString().slice(0, 10) !== parts[1]) {
  throw new Error('sale_timestamp is invalid');
}
const utcTimestamp = date.toISOString();
if (utcTimestamp.length !== 24 || utcTimestamp.startsWith('0000-')) {
  throw new Error('sale_timestamp is outside the supported range');
}

const fields = {
  sale_id: saleId,
  sale_timestamp: utcTimestamp,
  amount_cents: cents,
  refunded: flag(sale.refunded),
  test: flag(sale.test),
};
const optional = {
  buyer_email: text(sale.email) || text(sale.purchaser_email),
  product_id: text(sale.product_id),
  product_name: text(sale.product_name),
  currency: text(sale.currency).toUpperCase(),
};
for (const [name, value] of Object.entries(optional)) {
  if (value) fields[name] = value;
}

return {
  json: {
    performUpsert: { fieldsToMergeOn: ['sale_id'] },
    records: [{ fields }],
  },
};
